const { Given, When, Then, After } = require('@cucumber/cucumber');
const { expect } = require('expect');

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js. No action needed.
});

Given('the todo list is empty', function () {
  // Verify the list is empty, then clear any localStorage leftovers
  const list = this.document.querySelector('.todo-list');
  expect(list.children.length).toBe(0);
  // Also clear localStorage to ensure clean state
  this.localStorage.clear();
});

// ---------------------------------------------------------------------------
// When — creating
// ---------------------------------------------------------------------------

When('I type {string} into the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
});

When('I type {string} into the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

// ---------------------------------------------------------------------------
// When — toggling
// ---------------------------------------------------------------------------

When('I click the toggle checkbox on the todo', function () {
  const toggle = this.document.querySelector('.todo-list li .toggle');
  if (!toggle) throw new Error('No todo toggle found');
  toggle.click();
});

When('I click the toggle checkbox on {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.querySelector('.toggle').click();
      return;
    }
  }
  throw new Error(`No todo found with title "${title}"`);
});

When('I click the "Mark all as complete" toggle', function () {
  const toggle = this.document.getElementById('toggle-all');
  if (!toggle) throw new Error('No toggle-all checkbox found');
  toggle.click();
});

// ---------------------------------------------------------------------------
// When — destroying
// ---------------------------------------------------------------------------

When('I click the destroy button on the todo', function () {
  const btn = this.document.querySelector('.todo-list li .destroy');
  if (!btn) throw new Error('No destroy button found');
  // The destroy button is only visible on hover. Force click via dispatch.
  btn.click();
});

// ---------------------------------------------------------------------------
// When — editing
// ---------------------------------------------------------------------------

When('I double-click the todo label', function () {
  const label = this.document.querySelector('.todo-list li label');
  if (!label) throw new Error('No todo label found');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I type {string} into the edit input and press Enter', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I type {string} into the edit input and blur', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I type {string} into the edit input and press Escape', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true })
  );
});

When('I clear the edit input and blur', function () {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = '';
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

// ---------------------------------------------------------------------------
// When — clearing completed
// ---------------------------------------------------------------------------

When('I click the "Clear completed" button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button found');
  btn.click();
});

// ---------------------------------------------------------------------------
// When — routing
// ---------------------------------------------------------------------------

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I click the {string} filter link', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === name) {
      a.click();
      return;
    }
  }
  throw new Error(`No filter link "${name}" found`);
});

// ---------------------------------------------------------------------------
// When — negative / special
// ---------------------------------------------------------------------------

When('I click the toggle checkbox on {string} again', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.querySelector('.toggle').click();
      return;
    }
  }
  throw new Error(`No todo found with title "${title}"`);
});

// ---------------------------------------------------------------------------
// Then — list state
// ---------------------------------------------------------------------------

Then('the todo list shows {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(count);
});

Then('the todo list shows {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(count);
});

Then('the new todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).toBe('');
});

Then('the todo list shows 1 item titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(1);
  const label = items[0].querySelector('label');
  expect(label.textContent.trim()).toBe(title);
});

Then('the todo list is still empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(0);
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(0);
});

// ---------------------------------------------------------------------------
// Then — visibility
// ---------------------------------------------------------------------------

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  // Checking both display none and hidden style
  const style = this.window.getComputedStyle(main);
  expect(style.display).toBe('none');
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  expect(style.display).toBe('none');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  expect(style.display).not.toBe('none');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  expect(style.display).not.toBe('none');
});

Then('the "Clear completed" button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(btn);
  expect(style.display).toBe('none');
});

// ---------------------------------------------------------------------------
// Then — todo state
// ---------------------------------------------------------------------------

Then('the todo is marked as completed', function () {
  const li = this.document.querySelector('.todo-list li');
  expect(li.classList.contains('completed')).toBe(true);
  const toggle = li.querySelector('.toggle');
  expect(toggle.checked).toBe(true);
});

Then('the todo is no longer marked as completed', function () {
  const li = this.document.querySelector('.todo-list li');
  expect(li.classList.contains('completed')).toBe(false);
  const toggle = li.querySelector('.toggle');
  expect(toggle.checked).toBe(false);
});

Then('all todos are marked as completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBeGreaterThan(0);
  for (const li of items) {
    expect(li.classList.contains('completed')).toBe(true);
  }
});

Then('the "Mark all as complete" toggle is checked', function () {
  const toggle = this.document.getElementById('toggle-all');
  expect(toggle.checked).toBe(true);
});

Then('the "Mark all as complete" toggle is still checked', function () {
  const toggle = this.document.getElementById('toggle-all');
  expect(toggle.checked).toBe(true);
});

// ---------------------------------------------------------------------------
// Then — editing state
// ---------------------------------------------------------------------------

Then('the todo is in editing mode', function () {
  const li = this.document.querySelector('.todo-list li');
  expect(li.classList.contains('editing')).toBe(true);
  const edit = li.querySelector('.edit');
  expect(edit).not.toBeNull();
  expect(this.document.activeElement).toBe(edit);
});

// ---------------------------------------------------------------------------
// Then — count
// ---------------------------------------------------------------------------

Then('the todo count shows {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  expect(count.textContent.trim()).toBe(text);
});

Then('the count is wrapped in a strong element', function () {
  const strong = this.document.querySelector('.todo-count strong');
  expect(strong).not.toBeNull();
});

// ---------------------------------------------------------------------------
// Then — persistence
// ---------------------------------------------------------------------------

Then('localStorage contains {int} todos', function (count) {
  const data = this.localStorage.getItem('todos-vanillajs');
  expect(data).not.toBeNull();
  const todos = JSON.parse(data);
  expect(Array.isArray(todos)).toBe(true);
  expect(todos.length).toBe(count);
});

Then('the todos are persisted with keys id, title, and completed', function () {
  const data = this.localStorage.getItem('todos-vanillajs');
  const todos = JSON.parse(data);
  for (const todo of todos) {
    expect(todo).toHaveProperty('id');
    expect(todo).toHaveProperty('title');
    expect(todo).toHaveProperty('completed');
  }
});

// ---------------------------------------------------------------------------
// Then — routing
// ---------------------------------------------------------------------------

Then('the route {string} shows both todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(2);
});

Then('only active todos are shown', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    expect(li.classList.contains('completed')).toBe(false);
  }
});

Then('only completed todos are shown', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBeGreaterThan(0);
  for (const li of items) {
    expect(li.classList.contains('completed')).toBe(true);
  }
});

Then('the {string} filter link has the {string} class', function (name, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === name) {
      expect(a.classList.contains(className)).toBe(true);
      return;
    }
  }
  throw new Error(`No filter link "${name}" found`);
});

// ---------------------------------------------------------------------------
// And — chained When (for "and when I click...")
// ---------------------------------------------------------------------------

When('I do not complete any todos', function () {
  // No-op: ensures no todos are completed
});

When('the todo list shows 1 item titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).toBe(1);
  const label = items[0].querySelector('label');
  expect(label.textContent.trim()).toBe(title);
});

/*global todoify */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  var todoModel = {
    // Load from localStorage
    load: function () {
      try {
        var data = localStorage.getItem(STORAGE_KEY);
        return data ? JSON.parse(data) : [];
      } catch (e) {
        return [];
      }
    },

    // Save to localStorage
    save: function (todos) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    },

    // Generate a unique id
    uid: function () {
      return Date.now() + Math.random().toString(36).slice(2, 7);
    }
  };

  // -----------------------------------------------------------------------
  // App
  // -----------------------------------------------------------------------

  var app = {
    todos: [],
    filter: 'all',

    // DOM refs
    $newTodo: null,
    $main: null,
    $footer: null,
    $toggleAll: null,
    $todoList: null,
    $todoCount: null,
    $clearCompleted: null,
    $filters: null,

    // Init
    init: function () {
      this.$newTodo = document.querySelector('.new-todo');
      this.$main = document.querySelector('.main');
      this.$footer = document.querySelector('.footer');
      this.$toggleAll = document.getElementById('toggle-all');
      this.$todoList = document.querySelector('.todo-list');
      this.$todoCount = document.querySelector('.todo-count');
      this.$clearCompleted = document.querySelector('.clear-completed');
      this.$filters = document.querySelector('.filters');

      this.todos = todoModel.load();
      this.bindEvents();
      this.filter = this.getFilterFromHash();
      this.render();
    },

    // Get filter from URL hash
    getFilterFromHash: function () {
      var hash = window.location.hash.replace('#/', '') || 'all';
      if (hash === 'all' || hash === 'active' || hash === 'completed') {
        return hash;
      }
      return 'all';
    },

    // Bind all events
    bindEvents: function () {
      var self = this;

      // New todo
      this.$newTodo.addEventListener('change', function () {
        self.addTodo();
      });
      this.$newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          self.addTodo();
        }
      });

      // Toggle all
      this.$toggleAll.addEventListener('change', function () {
        self.toggleAll(this.checked);
      });

      // Clear completed
      this.$clearCompleted.addEventListener('click', function () {
        self.clearCompleted();
      });

      // Routing
      window.addEventListener('hashchange', function () {
        self.filter = self.getFilterFromHash();
        self.render();
      });
    },

    // Add a new todo
    addTodo: function () {
      var title = this.$newTodo.value.trim();
      if (title === '') {
        this.$newTodo.value = '';
        return;
      }

      this.todos.push({
        id: todoModel.uid(),
        title: title,
        completed: false
      });

      this.$newTodo.value = '';
      this.saveAndRender();
    },

    // Toggle a todo's completed state
    toggleTodo: function (id) {
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].completed = !this.todos[i].completed;
          break;
        }
      }
      this.saveAndRender();
    },

    // Toggle all todos
    toggleAll: function (checked) {
      for (var i = 0; i < this.todos.length; i++) {
        this.todos[i].completed = checked;
      }
      this.saveAndRender();
    },

    // Delete a todo
    destroyTodo: function (id) {
      var todos = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id !== id) {
          todos.push(this.todos[i]);
        }
      }
      this.todos = todos;
      this.saveAndRender();
    },

    // Clear completed todos
    clearCompleted: function () {
      var todos = [];
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) {
          todos.push(this.todos[i]);
        }
      }
      this.todos = todos;
      this.saveAndRender();
    },

    // Save edit
    editTodo: function (id, title) {
      var trimmed = title.trim();
      if (trimmed === '') {
        this.destroyTodo(id);
        return;
      }
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].title = trimmed;
          break;
        }
      }
      this.saveAndRender();
    },

    // Save and render
    saveAndRender: function () {
      todoModel.save(this.todos);
      this.render();
    },

    // Get filtered todos
    getFilteredTodos: function () {
      if (this.filter === 'active') {
        return this.todos.filter(function (t) { return !t.completed; });
      }
      if (this.filter === 'completed') {
        return this.todos.filter(function (t) { return t.completed; });
      }
      return this.todos;
    },

    // Count active todos
    activeCount: function () {
      var count = 0;
      for (var i = 0; i < this.todos.length; i++) {
        if (!this.todos[i].completed) count++;
      }
      return count;
    },

    // Count completed todos
    completedCount: function () {
      var count = 0;
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].completed) count++;
      }
      return count;
    },

    // Render the entire view
    render: function () {
      var self = this;
      var filtered = this.getFilteredTodos();
      var activeCount = this.activeCount();
      var completedCount = this.completedCount();

      // Show/hide main and footer
      var hasTodos = this.todos.length > 0;
      this.$main.style.display = hasTodos ? 'block' : 'none';
      this.$footer.style.display = hasTodos ? 'block' : 'none';

      // Toggle all checkbox
      this.$toggleAll.checked = activeCount === 0 && this.todos.length > 0;

      // Clear completed button
      this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

      // Render todo list
      var html = '';
      for (var i = 0; i < filtered.length; i++) {
        var todo = filtered[i];
        var liClass = '';
        if (todo.completed) liClass += ' completed';
        html += '<li' + (liClass ? ' class="' + liClass.trim() + '"' : '') + ' data-id="' + todo.id + '">';
        html += '  <div class="view">';
        html += '    <input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
        html += '    <label>' + self.escapeHtml(todo.title) + '</label>';
        html += '    <button class="destroy"></button>';
        html += '  </div>';
        html += '  <input class="edit" value="' + self.escapeHtml(todo.title) + '">';
        html += '</li>';
      }
      this.$todoList.innerHTML = html;

      // Update count
      var itemWord = activeCount === 1 ? 'item' : 'items';
      this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

      // Update filter links
      var filterLinks = this.$filters.querySelectorAll('a');
      for (var j = 0; j < filterLinks.length; j++) {
        var a = filterLinks[j];
        var href = a.getAttribute('href');
        var filterName = href.replace('#/', '') || 'all';
        if (filterName === '') filterName = 'all';
        if (filterName === this.filter) {
          a.classList.add('selected');
        } else {
          a.classList.remove('selected');
        }
      }

      // Bind events on rendered items
      this.bindItemEvents();
    },

    // Bind events to todo list items
    bindItemEvents: function () {
      var self = this;
      var items = this.$todoList.querySelectorAll('li');

      for (var i = 0; i < items.length; i++) {
        var li = items[i];
        var id = li.getAttribute('data-id');

        // Toggle checkbox
        var toggle = li.querySelector('.toggle');
        (function (todoId) {
          toggle.addEventListener('change', function () {
            self.toggleTodo(todoId);
          });
        })(id);

        // Destroy button
        var destroy = li.querySelector('.destroy');
        (function (todoId) {
          destroy.addEventListener('click', function () {
            self.destroyTodo(todoId);
          });
        })(id);

        // Double-click label to edit
        var label = li.querySelector('label');
        (function (todoId, liElement) {
          label.addEventListener('dblclick', function () {
            self.editMode(liElement, todoId);
          });
        })(id, li);
      }
    },

    // Enter editing mode
    editMode: function (li, id) {
      var self = this;
      li.classList.add('editing');

      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.value = li.querySelector('label').textContent;

      // Save on blur
      var onBlur = function () {
        self.editTodo(id, editInput.value);
        li.classList.remove('editing');
        editInput.removeEventListener('blur', onBlur);
        editInput.removeEventListener('keydown', onKeydown);
      };

      // Save on enter, discard on escape
      var onKeydown = function (e) {
        if (e.keyCode === ENTER_KEY) {
          editInput.blur();
        } else if (e.keyCode === ESCAPE_KEY) {
          editInput.value = li.querySelector('label').textContent;
          li.classList.remove('editing');
          editInput.removeEventListener('blur', onBlur);
          editInput.removeEventListener('keydown', onKeydown);
        }
      };

      editInput.addEventListener('blur', onBlur);
      editInput.addEventListener('keydown', onKeydown);
    },

    // Escape HTML for safe rendering
    escapeHtml: function (text) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(text));
      return div.innerHTML;
    }
  };

  // -----------------------------------------------------------------------
  // Boot
  // -----------------------------------------------------------------------

  app.init();
})();

